/**
 * Repair array-valued track references after the dedupe.
 *
 * `SystemPlaylist.trackIds` and `UserMix.trackIds` are text[] columns, not
 * foreign keys, so Postgres never validated them and the dedupe left them
 * pointing at deleted rows. FK-backed tables were repointed during the
 * migration; these two need doing by hand.
 *
 * Dead ids are stripped rather than remapped, because the mapping died with the
 * rows. That's safe for both: system playlists are rebuilt from the provider
 * charts on the next refresh, and user mixes carry an `expiresAt` and are
 * regenerated by `generateUserMixes`. Emptied mixes are deleted outright so the
 * home page treats them as absent and regenerates, instead of rendering a
 * shelf with two songs in it.
 *
 * Run with --apply to commit; default is a dry run.
 */
const path = require("path");
require("dotenv").config({ path: path.resolve(__dirname, "..", ".env"), quiet: true });
const { Pool } = require("pg");

const APPLY = process.argv.includes("--apply");

(async () => {
  const pool = new Pool({ connectionString: process.env.DATABASE_URL, max: 3 });
  const client = await pool.connect();

  try {
    await client.query("BEGIN");

    // Strip ids with no surviving Track. array_remove can't do this (it matches
    // values, not a predicate), so rebuild the array from a filtered unnest.
    const sp = await client.query(`
      UPDATE "SystemPlaylist" sp
         SET "trackIds" = COALESCE((
               SELECT ARRAY_AGG(tid ORDER BY ord)
                 FROM UNNEST(sp."trackIds") WITH ORDINALITY AS u(tid, ord)
                WHERE EXISTS (SELECT 1 FROM "Track" t WHERE t.id = u.tid)
             ), ARRAY[]::text[])
       WHERE EXISTS (
               SELECT 1 FROM UNNEST(sp."trackIds") AS tid
                WHERE NOT EXISTS (SELECT 1 FROM "Track" t WHERE t.id = tid)
             )
      RETURNING "systemId", COALESCE(array_length("trackIds", 1), 0) AS remaining
    `);
    console.log(`\n  System playlists cleaned: ${sp.rowCount}`);
    for (const r of sp.rows) console.log(`    ${r.systemId} → ${r.remaining} valid tracks`);

    const um = await client.query(`
      UPDATE "UserMix" m
         SET "trackIds" = COALESCE((
               SELECT ARRAY_AGG(tid ORDER BY ord)
                 FROM UNNEST(m."trackIds") WITH ORDINALITY AS u(tid, ord)
                WHERE EXISTS (SELECT 1 FROM "Track" t WHERE t.id = u.tid)
             ), ARRAY[]::text[])
       WHERE EXISTS (
               SELECT 1 FROM UNNEST(m."trackIds") AS tid
                WHERE NOT EXISTS (SELECT 1 FROM "Track" t WHERE t.id = tid)
             )
      RETURNING id
    `);
    console.log(`  User mixes cleaned: ${um.rowCount}`);

    // A mix too thin to be worth showing is worse than no mix — the home page
    // regenerates when it finds none.
    const dead = await client.query(
      `DELETE FROM "UserMix" WHERE COALESCE(array_length("trackIds", 1), 0) < 5 RETURNING id`
    );
    console.log(`  Under-filled mixes deleted (regenerate on next home load): ${dead.rowCount}`);

    // Expire the charts so the next home render rebuilds them against the
    // deduped catalogue rather than serving the thinned-out lists.
    const staled = await client.query(
      `UPDATE "SystemPlaylist" SET "updatedAt" = NOW() - INTERVAL '2 days' RETURNING "systemId"`
    );
    console.log(`  Charts marked stale for refresh: ${staled.rowCount}`);

    if (APPLY) {
      await client.query("COMMIT");
      console.log("\n  COMMITTED ✓\n");
    } else {
      await client.query("ROLLBACK");
      console.log("\n  DRY RUN — rolled back. Re-run with --apply.\n");
    }
  } catch (e) {
    await client.query("ROLLBACK");
    console.error("\nFAILED, rolled back:", e.message, "\n");
    process.exitCode = 1;
  } finally {
    client.release();
    await pool.end();
  }
})();
